import React from "react";

const Logo = ({ size }: { size?: number }) => {
  return (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      xmlnsXlink="http://www.w3.org/1999/xlink"
      width={size}
      zoomAndPan="magnify"
      viewBox="0 0 375 374.999991"
      height={size}
      preserveAspectRatio="xMidYMid meet"
      version="1.0"
    >
      <defs>
        <image
          x="0"
          y="0"
          width={size}
          xlinkHref="data:image/jpeg;base64,"
          id="d055981dd8"
          height="1563"
          preserveAspectRatio="xMidYMid meet"
        />
      </defs>
      <rect
        // x="-37.5"
        width={size}
        // fill="#ffffff"
        // y="-37.499999"
        height={size}
        fillOpacity="1"
      />
      <rect
        // x="-37.5"
        width={size}
        // fill="#ffffff"
        // y="-37.499999"
        height={size}
        fillOpacity="1"
      />
      <g transform="matrix(0.239923, 0, 0, 0.239923, 0.0000045, -0.000000000000054552)">
        <image
          x="0"
          y="0"
          width="1563"
          xlinkHref="data:image/jpeg;base64,"
          height="1563"
          preserveAspectRatio="xMidYMid meet"
        />
      </g>
    </svg>
  );
};

export default Logo;
